'use strict';
// SCULPT OP-07 · comparative tests: the RUBIK port (mm) against the donor's own outputs (cm, golden-771c9e1.json,
// generated by running the donor functions at 771c9e1) and against today's RUBIK consumers for straight walls.
const test=require('node:test'),assert=require('node:assert/strict'),path=require('node:path');
const G=require('../wall-geometry-core.js');
const golden=require('./golden-771c9e1.json');
const repo=path.resolve(__dirname,'../../../..');
const Core=require(path.join(repo,'js/project-core.js')),Q=require(path.join(repo,'js/quantity-core.js'));

const MM=10; // donor centimetres → RUBIK millimetres
const near=(a,b,tol=1e-6,msg='')=>assert.ok(Math.abs(a-b)<=tol*Math.max(1,Math.abs(b)),`${msg} ${a} ≠ ${b}`);
const nearPt=(a,b,msg)=>{near(a.x,b.x*MM,1e-9,msg+'.x');near(a.y,b.y*MM,1e-9,msg+'.y');};
/** donor wall (cm, curvePoint, startHeight/endHeight) → canonical RUBIK wall + proposed optional fields */
function toRubik(w){const s=w.startHeight??w.height,e=w.endHeight??w.height;
 return {id:w.id,start:{x:w.start.x*MM,y:w.start.y*MM},end:{x:w.end.x*MM,y:w.end.y*MM},thicknessMm:w.thickness*MM,heightMm:s*MM,
  ...(e!==s?{heightEndMm:e*MM}:{}),...(w.curvePoint?{curve:{control:{x:w.curvePoint.x*MM,y:w.curvePoint.y*MM}}}:{})};}
/** the golden used a door (centre 0.3, 90 wide, 210 high) and a window (centre 0.7, 120 wide, sill 90, 100 high) */
function openingsFor(g,w){const p=G.pathProfile(w),[d,win]=g.distanceAt;
 return [{id:'d',kind:'door',offsetMm:(d-45)*MM,widthMm:900,sillHeightMm:0,heightMm:2100},{id:'w',kind:'window',offsetMm:(win-60)*MM,widthMm:1200,sillHeightMm:900,heightMm:1000}];}

for(const g of golden.walls){
 const w=toRubik(g.wall);
 test(`donor parity · ${g.wall.id}: path, samples, bounds, label, split`,()=>{
  const p=G.pathProfile(w);near(p.length,g.length*MM,1e-9,'length');assert.equal(p.spans.length,g.facets);
  [0,.25,.5,.75,1].forEach((f,i)=>{const s=p.sample(p.length*f);nearPt(s.point,g.samples[i].point,`sample${i}`);near(s.height,g.samples[i].height*MM,1e-9,'h');});
  g.distanceAt.forEach((d,i)=>near(p.distanceAt([.3,.7][i]),d*MM,1e-9,'distanceAt'));
  for(const k of ['minX','maxX','minY','maxY'])near(G.bounds(w)[k],g.bounds[k]*MM,1e-9,k);
  const dim=G.dimension(w);near(dim.length,g.dimension.length*MM,MM,'label length (rounding unit)');nearPt(dim.point,g.dimension.point,'label');
  const sp=G.split(w,.4);for(const part of ['first','second']){nearPt(sp[part].start,g.split[part].start,part);nearPt(sp[part].end,g.split[part].end,part);
   assert.equal(!!sp[part].curve,!!g.split[part].curvePoint);if(sp[part].curve)nearPt(sp[part].curve.control,g.split[part].curvePoint,part+'.control');}
 });
 test(`donor parity · ${g.wall.id}: wall faces cut around a door and a window`,()=>{
  const prof=G.profileSpans(w,openingsFor(g,w));assert.equal(prof.length,g.profile.length);
  prof.forEach((s,i)=>{const d=g.profile[i];near(s.from,d.from*MM,1e-9,'from');assert.equal(s.segments.length,d.segments.length,`span ${i} segments`);
   s.segments.forEach((seg,j)=>{for(const k of ['width','offsetX','bottomY','topYLeft','topYRight'])near(seg[k],d.segments[j][k]*MM,1e-7,`span${i}.seg${j}.${k}`);});});
 });
}

test('donor parity · openings clipped under a sloped top (drawing only)',()=>{
 const w=toRubik(golden.walls.find(g=>g.wall.id==='sloped').wall),p=G.pathProfile(w);
 const cases=[[.9,120,90,100],[.1,90,0,210],[.99,120,0,210]];
 cases.forEach(([pos,width,sill,h],i)=>{const o=G.pathOpening(p,(pos*600-width/2)*MM,width*MM,sill*MM,h*MM),d=golden.openingOnWall[i];
  if(!d)return assert.equal(o,null);for(const k of ['left','right','bottom','top'])near(o[k],d[k]*MM,1e-9,`case${i}.${k}`);});
});

test('donor parity · rooms: centreline ring, area, interior area less wall footprints, ceiling',()=>{
 const W=(id,s,e,extra={})=>toRubik({id,start:{x:s[0],y:s[1]},end:{x:e[0],y:e[1]},thickness:15,height:250,...extra});
 const sets={square:[W('a',[0,0],[400,0]),W('b',[400,0],[400,300]),W('c',[400,300],[0,300]),W('d',[0,300],[0,0])],
  curvedSide:[W('a',[0,0],[400,0],{curvePoint:{x:200,y:-120}}),W('b',[400,0],[400,300]),W('c',[400,300],[0,300]),W('d',[0,300],[0,0])]};
 for(const [name,walls] of Object.entries(sets)){const g=golden[name],ring=G.roomRing(walls);
  assert.equal(ring.length,g.polygonPoints,name+' ring points');assert.equal(G.ringArea(ring),g.area,name+' area m²');
  near(G.interiorArea(ring,[],walls),g.interiorArea,1e-9,name+' interior m²');assert.equal(G.roomCeiling(walls),g.ceiling*MM);}
});

// ── RUBIK consumers: a wall without the new fields must measure exactly as today ─────────────────────────────────────
test('RUBIK parity · straight wall: quantity-core face areas equal the lab faces (project from project-core)',()=>{
 const p=Core.initial();let checked=0;
 for(const w of p.walls){const qty=Q.wall(p,w);if(!qty.complete)continue;const ops=p.openings.filter(o=>o.wallId===w.id),f=G.faceAreas(w,ops);
  near(f.lengthMm/1000,qty.quantities.lengthM,1e-12,w.id+' length');near(f.grossMm2/1e6,qty.quantities.faceGrossAreaM2,1e-12,w.id+' gross');
  near(f.netMm2/1e6,qty.quantities.faceNetAreaM2,1e-9,w.id+' net');near(f.leftFaceMm,f.rightFaceMm,1e-12,'equal faces');checked++;}
 assert.ok(checked>0,'the reference project has measurable walls');
});
test('RUBIK parity · straight wall: project-core plan pieces equal the full-height lab pieces',()=>{
 const p=Core.initial(),geo=Core.geometry(p);
 for(const w of p.walls){const solid=geo.walls.filter(r=>r.id===w.id).reduce((s,r)=>s+r.spanMm,0),ops=p.openings.filter(o=>o.wallId===w.id);
  const lab=G.profileSpans(w,ops)[0].segments.filter(s=>s.bottomY===0&&s.topYLeft===w.heightMm).reduce((s,x)=>s+x.width,0);near(lab,solid,1e-9,w.id);}
});
test('contract · production is unchanged: project-core still rejects the proposed fields (no contract change in OP-07)',()=>{
 for(const extra of [{curve:{control:{x:0,y:0}}},{heightEndMm:2000}]){const p=Core.initial();Object.assign(p.walls[0],extra);assert.throws(()=>Core.validate(p),/unknown field/);}
});

// ── What RUBIK adds over the donor ──────────────────────────────────────────────────────────────────────────────────
const sloped={id:'s',start:{x:0,y:0},end:{x:6000,y:0},thicknessMm:150,heightMm:2500,heightEndMm:1200};
const arc={id:'c',start:{x:0,y:0},end:{x:4000,y:0},thicknessMm:150,heightMm:2500,curve:{control:{x:2000,y:1500}}};
test('openings · validation reports what the donor would silently clip',()=>{
 assert.deepEqual(G.validateOpening(sloped,{offsetMm:4800,widthMm:1200,sillHeightMm:900,heightMm:1000}),['opening exceeds wall height']);
 assert.deepEqual(G.validateOpening(sloped,{offsetMm:300,widthMm:900,sillHeightMm:0,heightMm:2100}),[]);
 assert.deepEqual(G.validateOpening(arc,{offsetMm:G.pathProfile(arc).length-500,widthMm:900,sillHeightMm:0,heightMm:2100}),['opening extends beyond wall']);
});
test('openings · offsetMm is a physical distance along the curve (no parameter drift)',()=>{
 const o={offsetMm:1000,widthMm:900,sillHeightMm:0,heightMm:2100},hole=G.profileSpans(arc,[o]);
 const gap=hole.flatMap(s=>s.segments.filter(g=>g.bottomY>0).map(g=>g.width)).reduce((a,b)=>a+b,0);near(gap,900,1e-9,'door gap measured along the path');
});
test('split · at a distance keeps total length, height continuity and openings on their side',()=>{
 const ops=[{id:'a',offsetMm:200,widthMm:900,sillHeightMm:0,heightMm:1100},{id:'b',offsetMm:2600,widthMm:900,sillHeightMm:0,heightMm:1100},{id:'x',offsetMm:1500,widthMm:900,sillHeightMm:0,heightMm:1000}];
 for(const w of [sloped,arc]){const r=G.splitAt(w,2000,ops),L=G.pathProfile(w).length,a=G.pathProfile(r.first).length,b=G.pathProfile(r.second).length;
  near(a+b,L,w.curve?2e-3:1e-9,w.id+' length');assert.equal(G.endHeight(r.first),G.startHeight(r.second));
  assert.deepEqual(r.blocked,['x']);assert.equal(r.openings.find(o=>o.id==='b').part,'second');}
 const r=G.splitAt(sloped,2000);near(r.first.heightEndMm,2500-1300*2000/6000,1e-9,'height at split');
});
test('measurements · a curved wall has a longer outer face; a sloped wall a trapezoid face',()=>{
 const f=G.faceAreas(arc);assert.ok(f.leftFaceMm>f.lengthMm&&f.rightFaceMm<f.lengthMm,'outer > centreline > inner');
 near((f.leftFaceMm+f.rightFaceMm)/2,f.lengthMm,1e-3,'mean of faces ≈ centreline');
 near(G.faceAreas(sloped).grossMm2,6000*(2500+1200)/2,1e-12,'trapezoid');
 assert.equal(G.roomCeiling([sloped]),undefined,'no single ceiling height on a sloped boundary');
});
test('3D · sloped piece without Three.js: level piece is a box, sloped top normal is unit and tilted',()=>{
 const box=G.slopedPiece(1000,150,0,2500,2500),s=G.slopedPiece(1000,150,0,2500,1500);
 assert.equal(box.positions.length,72);assert.equal(box.indices.length,36);assert.deepEqual(box.normals.slice(24,27).map(v=>v+0),[0,1,0]);
 const [nx,ny]=s.normals.slice(24,26);near(Math.hypot(nx,ny),1,1e-12,'unit');assert.ok(nx>0&&ny>0);
 near(s.uvs[2*16+1],0,1e-12,'face v starts at floor');
});
test('compatibility · legacy view degrades visibly and never silently',()=>{
 const a=G.legacyView(arc),s=G.legacyView(sloped),plain=G.legacyView(Core.initial().walls[0]);
 assert.equal(a.wall.curve,undefined);assert.equal(a.loss[0].field,'curve');assert.ok(a.loss[0].pathMm>a.loss[0].chordMm);
 assert.equal(s.wall.heightMm,2500);assert.equal('heightEndMm' in s.wall,false);assert.equal(s.loss[0].field,'heightEndMm');
 assert.deepEqual(plain.loss,[]);
 assert.equal(G.facets(arc).length,G.FACETS+1);assert.equal(G.facets(sloped).length,2);
});
